"""Inspectable diblock SI review; preserve unresolved variants and main access."""
import json,re,subprocess
import ledger as L
from review_batch_0001 import evidence

def main():
 key='10.1021/acsnano.6b07291';rid='author-priority-thomas-labean';batch='AUTHOR0030';before=L.counts();base=L.ROOT/'assets/research-20261105';si=base/'diblock-si.pdf'
 ev=evidence(si,'https://ndownloader.figshare.com/files/7321154','Entire SI S1–S18 text inspected; S2 routing/cross-section and S9 colored capture boundaries visually inspected. TableS1 S2–S12; tall rectangle experiments S14/S16–17.')
 ce=evidence(base/'diblock-crossref.json','https://api.crossref.org/works/'+key,'Publisher-deposited bibliography; all entries retained as citation leads, not scientific decisions.')
 s=subprocess.check_output(['pdftotext','-layout',str(si),'-']).decode();rows=[]
 for page,t in enumerate(s.split('\f'),1):
  for n,seq,pos in re.findall(r's #333333\s*\n(\d+)\s+([ACGT]+)\s+(\d+\[\d+\])',t):rows.append(dict(name='s '+n,sequence=seq,map_position=pos,pdf_page=page))
 assert len(rows)==72 and {r['name'] for r in rows}=={'s '+str(i) for i in range(1,73)}
 arms=re.findall(r'arm ([A-F])\s*(?:[ACGT]+\s*)?#[a-f0-9]+ (\d+)',s)
 crowns=re.findall(r'crown ([A-F]+)\s*(?:[ACGT]+\s*)?#[a-f0-9]+ (\d+)',s)
 assert len(arms)==48 and set(arms)=={(c,str(i)) for c in 'ABCDEF' for i in range(1,9)}
 assert len(crowns)==24 and set(crowns)=={(c,str(i)) for c in ['ABE','BCD','DEF','ACF'] for i in range(1,7)}
 L.atomic(L.HERE/'diblock_sequence_index.json',json.dumps(dict(evidence=ev,structural_rows=rows,arm_names=[c+' '+n for c,n in arms],crown_names=[c+' '+n for c,n in crowns],table_total=144,separate_nanoparticle_coating_oligos=2,limitations='72 structural sequences text-indexed, not independently base-by-base certified. 48 arm and24 crown sequences not transcribed: colored capture boundaries and line wraps require systematic source-image checks. Optional captures cannot be removed merely by trimming polyA runs.144rows is not proof of complete routing or synthesis set.'),indent=2)+'\n')
 qs=['Acquire journal main and compare two reported tetrahedral variants with this single SI routing/table; exact variant distinction remains unresolved.','Obtain native routing and full scaffold identity/sequence; verify all144table sequences and colored optional-capture boundaries without heuristic trimming.','Resolve tall rectangle parent and exact corner capture modifications; its source table is not supplied here.','Review Estrich dissertation via alternate repository route; direct bitstream returned non-PDF. Do not equate that response with institutional entitlement failure.','Continue independent author histories and backward/forward citations; FNANO deferred.']
 note='SI establishes actual origami use. S2–S12 provides one tetrahedral caDNAno routing/cross-section and144named staple rows:72 s,48arm(A–F each1–8),24crown(ABE/BCD/DEF/ACF each1–6). S2 caption permits red/green capture segments to be omitted or changed; crown strands also hold vertices. S12 separately lists two thiolated nanoparticle-coating oligos. S18 uses4488bp per tetrahedron in a calculation, not full scaffold length. S14/S16–17 explicitly uses tall rectangle origami for nuclease protection and gold-sphere corner hybridization. Protein concentration/treatment controls are not automatically new DNA geometries. Main unavailable: exact tetrahedral variants, parent identities, full scaffold/native routing and catalog geometry eligibility remain unresolved.'
 p=next(p for p in L.read('publication_reviews') if p['registry_key']==key)
 p.update(review_stage='design_sources_reviewed',relevance='design_bearing',design_contributions=['uncertain'],catalog_eligibility='unresolved',rationale=note,reviewer='Codex SI text and selected source-image review',run_id=rid,date=L.DATE,unresolved_questions=qs)
 for e in [ev,ce]:
  if e not in p['evidence']:p['evidence'].append(e)
 L.upsert('publication_reviews',p,'Confirm experimental origami and source table; retain variant, parent and geometry uncertainty')
 for did,names,loc,detail in [('RDE0055',['Tetrahedral DNA origami, SI routing/table'],'S2–S12/S18','Six named arm sets and four crown sets; caDNAno cross-section includes helix labels0–30, but screenshot alone does not certify 3D topology or packing. Whole-object geometry/variant review pending main.'),('RDE0056',['Tall rectangle DNA origami with gold spheres at corners'],'S14/S16–17','Experimental planar rectangle use explicit; exact parent, staple list and corner capture combination pending. Do not infer lattice merely from rectangle name.')]:
  old=next((d for d in L.read('design_evidence') if d['design_id']==did),None);assert old is None or key in old['publication_keys']
  L.upsert('design_evidence',dict(design_id=did,publication_keys=[key],named_objects=names,identity_status='Reported experimental group; exact parent and variant reconciliation pending',lattice_decision=detail,catalog_eligibility='unresolved',core_variant_composition=note,relationships=[],variant_links=[],source_completeness='not_verified',source_files=[ev],evidence=[ev],outstanding_checks=qs,review_stage='source_reviewed',review_run=batch,run_id=rid,date=L.DATE,legacy_record={},locator=loc),'Preserve distinct documented groups without assuming source completeness')
 refs=json.loads((base/'diblock-crossref.json').read_text())['message']['reference']
 for i,r in enumerate(refs,1):
  L.upsert('discovery_edges',dict(edge_id='diblock:journal-reference:'+str(i),source_key=key,target_key=r.get('DOI','').lower() or 'citation:diblock:'+str(i),relation='cites',citation=r,evidence_url=ce['url'],local_file=ce['local_file'],sha256=ce['sha256'],locator='Deposited reference '+str(i),reconciliation_state='pending_identity_date_scope_reconciliation',run_id=rid,date=L.DATE),'Retain entire publisher-deposited reference list')
 L.upsert('discovery_edges',dict(edge_id='diblock:estrich-thesis-lead',source_key=key,target_key='lead:estrich-dissertation',relation='related_source_lead',evidence_url='https://repository.lib.ncsu.edu/bitstreams/927d8232-85bf-402e-811b-b15c31dc336d/download',locator='Search result identifies dissertation chapters on tetrahedra and diblock compatibilization; local acquisition non-PDF, contents not reviewed.',reconciliation_state='pending_acquisition_identity_date_and_variant_review',run_id=rid,date=L.DATE),'Retain repository source lead despite failed local acquisition')
 L.upsert('batches',dict(batch_id=batch,date=L.DATE,status='completed',input_keys=[key],selection='Low-keyword LaBean acquired SI scientific review',before_counts=before,after_counts=L.counts(),completed_actions=['Reviewed all18SI pages as extracted text and routing/colored-table images S2/S9.','Indexed72 structural rows and72 arm/crown names; preserved optional capture ambiguity.','Recorded tetrahedral and tall rectangle groups without unsupported lattice/source certification.',f'Retained all{len(refs)}deposited references and dissertation acquisition lead.'],validation=[L.validate()],unresolved_keys=[key],next_queue=qs),'Save source review with main and variant gaps explicit')
 print(len(refs),L.validate())
if __name__=='__main__':main()
